    for (let i = 0; i <= 40; i++) { const u = i / 40; candy.push([(12 + u * 78) * U, (50 - 34 * Math.exp(-((u - .28) ** 2) / .012) + (u > .28 ? 10 * seg(u, .28, .6) : 0)) * U]); veg.push([(12 + u * 78) * U, (46 - 16 * (1 - Math.exp(-u * 3))) * U]); }
    const f1 = seg(d, .15, .6), f2 = seg(d, .55, .95);
