    if (bk === 'quizzical') { up = sd > 0 ? .6 : -.05; rot = sd > 0 ? -.12 : .1; }
    const bx = sd * 2.1 + fx, by = -2.45 - up;
    X.save(); X.translate(bx, by); X.rotate(rot); shape(rectPts(-1.25, -.3, 2.5, .62), { fill: RS.hair, stroke: RS.ink, lw: lw * .8, smooth: .2 }); X.restore();
